R=[2,6,10,14,18,22,26]; C=[2,5,8,11,14,17,20,23]
M={(6,5):6,(6,8):6,(6,11):9,(6,14):9,(10,5):6,(10,8):6,(10,11):9,(10,14):9,(14,5):6,(14,8):6,(14,11):9,(14,14):9,(18,2):2,(18,5):2,(18,8):3,(18,11):3,(22,2):2,(22,5):2,(22,8):3,(22,11):3,(22,14):3,(26,8):3,(26,11):3,(26,14):3}
G=[]
for a,b in zip(R,R[1:]):
 row=[]
 for x,y in zip(C,C[1:]):
  q=[M.get((a,x),0),M.get((a,y),0),M.get((b,x),0),M.get((b,y),0)]
  row.append(q[0] if q[0]!=0 and len(set(q))==1 else 5)
 G.append(row)
print('raw',G)
# dedup consecutive rows, trim rows that are entirely default 5
D=[]
for row in G:
 if not D or row!=D[-1]: D.append(row)
while D and all(v==5 for v in D[0]): D.pop(0)
while D and all(v==5 for v in D[-1]): D.pop()
# remove all-default columns
if D:
 keep=[j for j in range(len(D[0])) if any(row[j]!=5 for row in D)]
 D=[[row[j] for j in keep] for row in D]
print('processed',D)

